#include <stdio.h>

int main() {
    printf("Hello world!\n");
    return 0;
}

// 3) using puts
#include <stdio.h>

int main() {
    puts("Hello world!");
    return 0;
}

// 4) using stringstream
#include <iostream>
#include <sstream>

int main() {
    std::stringstream ss;
    ss << "Hello world!";
    std::cout << ss.str() << std::endl;
    return 0;
}

// 5) using write
#include <unistd.h>
#include <string.h>

int main() {
    const char* s = "Hello world!\n";
    write(STDOUT_FILENO, s, strlen(s));
    return 0;
}
